exempt = (input('exempt_assets') || {})['CKV_AWS_353'] || []

control 'CKV_AWS_353' do
  title 'Ensure that RDS instances have performance insights enabled'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_db_instance resources that actually exist, read through the
    stock inspec-aws aws_rds_instance resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Performance Insights is what makes a slow-query or lock-contention
    question answerable after the fact rather than during the next incident.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_db_instance: performance_insights_enabled is
    True; aws_rds_cluster_instance: performance_insights_enabled is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_db_instance:

      resource "aws_db_instance" "example" {
        performance_insights_enabled = true
      }

    Out of band — aws_db_instance:

      aws rds modify-db-instance --db-instance-identifier <id> --enable-performance-insights --apply-immediately
  FIX

  tag checkov_id:            'CKV_AWS_353'
  tag checkov_category:      'LOGGING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_db_instance aws_rds_cluster_instance]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/db_instance#performance-insights-enabled'
  tag nist:                  ['AU-12', 'SI-4']
  tag nist_r4:               ['AU-12', 'SI-4']
  tag cci:                   ['CCI-000172', 'CCI-002664']
  tag ksi:                   ['KSI-MLA-LOG']
  tag severity:              'low'
  tag severity_source:       'assessed'
  tag nist_source:           'reviewed'
  tag implementation_status: 'implemented'

